from build_engine3 import *
import copy
oldpath=ROOT.parent/'expansion/yamaha/workshop-pass2/valve-adjustment-v3.procedure.json'
old=json.loads(oldpath.read_text()); by={s['id']:s for s in old['steps']}
camremove=[step('entry','Confirm cold engine-bench access','Engine is removed and supported with the original left cover/rotor installed so its timing marks can be used. Keep the engine at room temperature and do not use the starter. Exterior tank/body/throttle/exhaust access is already complete.',[214,217],'Cold supported engine and readable rotor/cover marks confirmed.')]
camremove += [copy.deepcopy(by[i]) for i in ['cover-remove','access','tdc','measure','tensioner-remove','cams-remove','tensioner-check']]
camremove += [step('handoff','Preserve the open timing state','Keep cams/caps/dowels in their exact original positions in labeled trays, keep the chain secured and record the crankTDC position. Cam inspection and head removal can now proceed; do not operate the starter or call this an installed/timed engine.',[217,219],'Original positions retained; chain secured; open state recorded.')]
procedure('cams-remove-bench-v1','Remove cams for engine overhaul',camremove,['Removed cold engine; left rotor/cover retained for timing reference.'],['Cams/caps/tensioner removed, chain secured and cold readings recorded; head remains installed.'],['Feeler gauges','Hand crank-rotation wrench; clean chain wire; metric tools','Thin screwdriver for tensioner check'],['Clean labeled trays and protective cloths'],['Cam installation/engine closure','Automatic declaration that recorded clearances are in range'],['engine','cams'])

camcheck=[
step('entry','Prepare the removed cams and matching head','Use the original matching head and caps on the bench, with cams removed and identified by intake/exhaust. Keep cap locations and dowels matched; a mixed cap set is not an acceptable measurement fixture.',[217,218],'Original matching caps/head confirmed.'),
step('lobes','Inspect and measure the lobes','Replace a cam with blue discoloration, pitting or scratches. Measure lobe height at the illustrated axis: intake limit38.030mm, exhaust34.170mm. Record each lobe measurement and condition.',[218],'All lobe heights and conditions saved.',True,True),
step('plastigauge','Measure cam journal clearance','Place the cam in its matching head and position a Plastigauge strip on the journal as shown. Install dowels/caps, tightening inward-to-outward in a crisscross pattern to10Nm. Do not rotate the cam during the measurement. Remove caps and read strip width using the product scale; required clearance0.028–0.062mm.',[218],'Each measured journal clearance recorded.',True,True),
step('journal','Identify the worn component when clearance fails','If a journal clearance is outside0.028–0.062mm, measure that cam journal diameter. Required diameter22.002–22.015mm. An out-of-spec diameter requires the cam; an in-spec diameter with failed clearance requires the head and matching caps as a set. Record the decision for each failed location.',[218],'Failed-location diameter and replacement decision recorded, or no failed clearance.'),
step('chain','Inspect chain and sprockets','Check chain damage/stiffness and sprocket tooth wear against the drawing. More than one-quarter tooth wear requires camshaft and timing chain as a set; damaged/stiff chain requires the stated matching replacement set. Do not return a defective sprocket to service with only a new chain.',[218,219],'Chain and sprocket results recorded.',True,True),
step('decompressor','Inspect the decompressor and preserve parts','Verify the decompressor cam moves smoothly and its lever pin projects from the camshaft. Record the results. Remove all Plastigauge residue before assembly and keep the inspected cams/caps labeled for the installation operation.',[218,219],'Decompressor result saved; measurement residue removed.',True,True)]
procedure('camshaft-inspection-bench-v1','Measure camshafts and journal clearance',camcheck,['Cams removed; their original matching head/caps available.'],['Cam/head inspection recorded and required replacement disposition determined; cams remain out.'],['Micrometer, Plastigauge covering0.028–0.062mm with its scale/instructions','Torque wrench accurate at10Nm'],['Exact stock replacement cams/head-cap set/chain if inspection requires'],['Engine access','Installation and final timing'],['engine','cams','cylinder_head'])

caminstall=[step('entry','Confirm readiness to time the rebuilt engine','Head, valves, original-position pads/lifters and cylinder are assembled and verified. Crankcases, rotor and left cover are installed with readable timing marks. Cams/tensioner are inspected and stock. Rotate the crankshaft counterclockwise by hand to align rotorTDC with its cover reference before cam installation.',[219,220],'Head ready; inspected parts; rotorTDC confirmed.',True,True)]
caminstall += [copy.deepcopy(by[i]) for i in ['cams-install','caps-install','tensioner-install','tensioner-release','timing-verify','remeasure','cover-install','plug-access-close']]
caminstall += [step('handoff','Record timed-engine completion','Save all four cold clearances and timing results. If a clearance is outside intake0.10–0.17mm or exhaust0.15–0.22mm, complete the reviewed pad-adjustment operation and repeat timing/clearance verification before engine installation or starting. Do not treat an out-of-range reading as a passed installation.',[91,92,221],'Timing and all four in-range cold readings saved; closures verified.',True)]
procedure('cams-install-bench-v1','Time and close the rebuilt top end',caminstall,['Head/cylinder installed; cams out; rotor/left cover present.','Inspected stock cams/tensioner and new sealing parts available.'],['Cams/tensioner installed; timing and four cold clearances verified; head cover/plug/access plugs closed.'],['Feeler gauges, hand rotation wrench, torque wrench accurate at6/10/13Nm','Thin screwdriver and chain retaining wire'],['New head-cover and plug-hole gaskets','ThreeBond1541C','New tensioner gaskets positions1/3/5','Two new timing-access O-rings','Engine oil, molybdenum-disulfide oil and lithium-soap grease'],['Unsupported pad-chart inputs','Warm-start/run commissioning and engine refit'],['engine','cams','cylinder_head'])

shift=[
step('entry','Confirm shift-mechanism access','Start with the clutch idle gear removed and right-side shift mechanism exposed. Retain the pedal alignment marks if the pedal is still fitted; remove its bolt/pedal before withdrawing the shaft.',[264,265,268],'Idle gear removed; pedal marks retained.'),
step('remove','Remove the shaft and selector parts','Withdraw shift shaft, collar and spring; retain the roller. Remove shift-guide bolts and lift guide/shift-lever assembly together, retaining both pawls, pins and springs by location. Turn the segment counterclockwise to its stop and loosen its bolt without impact. Remove segment, stopper lever/collar and spring.',[264,265,266],'Shaft/selector parts labeled; no impact on segment.',False,True),
step('inspect','Inspect every selector part','Replace bent/damaged/worn shift shaft or spring. Inspect guide, lever, both pawls/pins/springs and stopper lever for damage/wear; replace defective parts. Replace a broken stopper spring. Record the assessment.',[266],'Selector inspection and replacement list saved.'),
step('stopper','Install the stopper and segment','Fit stopper spring, collar and lever in the shown arrangement; tighten stopper bolt10Nm with LOCTITE. Push the stopper lever down and align segment projections with drum slits; install segment bolt30Nm without impact.',[266,267],'Stopper10Nm, segment30Nm and projection/slit alignment recorded.',True,True),
step('pawls','Build and fit the shift lever','Oil the two springs, pawl pins and pawls. Fit them in the illustrated lever pockets, then install lever into guide. Fit both together and tighten shift-guide bolts10Nm with LOCTITE.',[267],'Both pawls/pins/springs installed; guide10Nm recorded.',True,True),
step('shaft','Install shaft and new seal','Fit dowel, roller, shaft spring and collar in the illustrated locations. Oil the shaft and install it with the spring engaging as shown. Fit a new shift-shaft seal at0–1.0mm illustrated depth and lubricate its lip with lithium-soap grease.',[264,267],'Shaft spring engagement and new seal depth recorded.',True,True),
step('pedal','Refit the marked pedal and check movement','Align the punch marks on shaft and pedal; tighten pedal bolt12Nm. Operate the selector while turning the transmission by hand, checking smooth return and gear selection before the idle gear and covers are installed.',[267,268,292],'Pedal12Nm and selector movement saved.',True,True)]
procedure('shift-mechanism-bench-v1','Rebuild the shift mechanism',shift,['Clutch idle gear removed; selector exposed; transmission installed for final check.'],['Shift shaft/selector/pedal installed and function checked; clutch/cover closure remains.'],['Torque wrench accurate at10/12/30Nm; seal driver','Clean labeled trays'],['New shift-shaft oil seal','Engine oil, lithium-soap grease and LOCTITE'],['Transmission shaft rebuilding','Engine access and clutch closure'],['engine','transmission'])
manifest()
